package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaRemainderContextsTest {
 @Test public void gradeAndBoundsPreserveContextMeaning(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");CurriculumLimits limits=GlobalCurriculum.limits(p.educationSystem,RemainderContexts.GROUPS,3);Checker checker=new Checker();for(String id:List.of(RemainderContexts.GROUPS,RemainderContexts.LENGTH)){assertTrue(GlobalCurriculum.pack(p).inGrade(id,3));assertFalse(GlobalCurriculum.pack(p).inGrade(id,2));for(int n=10;n<=100;n++)for(int d=2;d<=10;d++){Question q=new Question(id,String.format(Locale.ROOT,RemainderContexts.template(id),n,d),"poison","poison");assertTrue(limits.allows(qWithAnswer(q,id,n,d)));q.answers=new String[]{"poison"};assertTrue(checker.check(q,List.of(),List.of(id.equals(RemainderContexts.GROUPS)?""+(n/d):n+"/"+d)).correct());RemainderContexts.attach(q);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.step(4).accepts(id.equals(RemainderContexts.GROUPS)?"groups":"share"));}}
 Question small=new Question(RemainderContexts.GROUPS,String.format(RemainderContexts.template(RemainderContexts.GROUPS),9,2),"","4");assertFalse(limits.allows(small));
 }
 private Question qWithAnswer(Question q,String id,int n,int d){q.expression="";q.answers=new String[]{id.equals(RemainderContexts.GROUPS)?""+(n/d):n+"/"+d};return q;}
 @Test public void tenMaximumIncludesSingleDigitDivisorsAndTen(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");for(String id:List.of(RemainderContexts.GROUPS,RemainderContexts.LENGTH)){Generator g=new Generator(new Random(209));CurriculumLimits l=GlobalCurriculum.limits(p.educationSystem,id,3);List<String> recent=new ArrayList<>();Set<Integer> divisors=new HashSet<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,l);int[] v=RemainderContexts.read(q);assertNotNull(v);assertTrue(v[0]>=10&&v[0]<=100);assertTrue(v[1]>=2&&v[1]<=10);assertTrue(l.allows(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());divisors.add(v[1]);}assertEquals(new HashSet<>(List.of(2,3,4,5,6,7,8,9,10)),divisors);}}
}
